// Runtime-local assets: Metro resolves these static require calls into the app bundle.
// The cuisine cover art is original flat-illustration work generated by
// `scripts/demo-art/build-art.mjs`. `coverFor()` picks one deterministically from
// a stable name hash, so every restaurant/drop gets an appetizing, consistent
// cover (with variety across restaurants) instead of a single grey placeholder.
// Real uploaded media still takes priority via ProductMedia's `media` prop.
const covers = [
  require("../../assets/art/cover-biryani.png"),
  require("../../assets/art/cover-thali.png"),
  require("../../assets/art/cover-grill.png"),
  require("../../assets/art/cover-coastal.png"),
  require("../../assets/art/cover-bakery.png"),
] as const;

function hashIndex(key: string, modulo: number): number {
  let hash = 0;
  for (const character of key.normalize("NFC")) hash = (hash * 31 + character.codePointAt(0)!) >>> 0;
  return hash % modulo;
}

/** Deterministic appetizing cover for a restaurant/drop, keyed by a stable name. */
export function coverFor(key: string | null | undefined) {
  const safe = (key ?? "").trim();
  return covers[safe ? hashIndex(safe, covers.length) : 0] ?? covers[0];
}

export const mediaFallbacks = {
  // Back-compat defaults for any call site without a key.
  drop: covers[0],
  restaurantCover: covers[1],
  coverFor,
} as const;
